import{_ as t,a as o,b as a,c as i,d as n,e as r,f as s,g as p,h as l}from"./chunks/b49b5672a450fb04b394.BHV6UKBl.js";import{_ as h,o as c,c as u,a6 as m}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"The Greatest Skill Of The 21st Century (The Top 1% Exploit This)","description":"","frontmatter":{"title":"The Greatest Skill Of The 21st Century (The Top 1% Exploit This)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md","filePath":"en/letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md"}'),d={name:"en/letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md"};function g(f,e,y,w,b,v){return c(),u("div",null,[...e[0]||(e[0]=[m('<h1 id="the-greatest-skill-of-the-21st-century-the-top-1-exploit-this" tabindex="-1">The Greatest Skill Of The 21st Century (The Top 1% Exploit This) <a class="header-anchor" href="#the-greatest-skill-of-the-21st-century-the-top-1-exploit-this" aria-label="Permalink to &quot;The Greatest Skill Of The 21st Century (The Top 1% Exploit This)&quot;">​</a></h1><p>Dan Koe · 2023-10-06 · <a href="https://thedankoe.com/letters/the-most-important-skill-of-the-21st-century-only-1-use-it/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/j5S5a7_pk60?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I’m going to be honest.</p><p>Myself and <a href="https://twitter.com/iamjustincscott" target="_blank" rel="noreferrer">Justin Scott</a> are having a newsletter writing competition.</p><p>We set out to write 7 newsletters in 7 days to have a backlog.</p><p>I even took it a step further and have been recording 7 YouTube videos day by day.</p><p>Today’s writing fell on a busy day, I was preparing Sprint curriculum calls.</p><p>So… I copy pasted this directly from <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> (it’s less than 1% of what’s in there).</p><p>In my eyes, it is one of the most important skills you can master: <strong>persuasive communication.</strong></p><p>That way, people actually share your writing (meaning you actually grow on social media).</p><p>As a bonus, I’ve included a download link to a PDF (no email required) with what we discuss in this letter.</p><p><a href="https://www.dropbox.com/scl/fi/nhvzkqzbzlp6ro6ocb8a4/ContentPresentation.pdf?rlkey=8kpb8t3wgc21wu9acqg33c80v&amp;dl=0" target="_blank" rel="noreferrer">Open this PDF in another tab so you don’t lose it.</a></p><p>I would highly encourage you have it open while writing content.</p><p>It includes the 10 Koemmandments of Engagement and 32 post structures you can emulate – my personal swipe file.</p><p>Let’s dive in:</p><p><strong>People don’t remember what you say, they remember how you make them feel.</strong></p><p>This is worth repeating:</p><p><em>Humans are emotional beings, not logical.</em></p><p>99% of the population have not developed themselves to the point of being free from — or in control of — their ego.</p><p>That is the foundation of capturing and holding attention.</p><p>Poking your reader’s ego.</p><p>Feeding it = making them feel “good.”</p><p>Starving it = making them feel “bad.”</p><p>If you can take people on an emotional journey of love, hate, excitement, deceit, calmness, and any other emotion that eventually ends in a benefit for their life — you have mastered the art of content creation.</p><p>Life is story.</p><p>Song is story (Uni-verse, one song).</p><p>Architecture, music, plant life, and everything else follow the Universal principles of highs/lows creation/destruction growth/death etc.</p><p>Humans make sense of the world in stories.</p><p>Your job is to use the power of word to make people <em>feel</em> something.</p><p>Stories mimic the natural highs and lows of emotion.</p><p>Before we start:</p><p>The Art Of Focus (my book) is <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">available for pre-order.</a></p><p>(This isn’t a normal book launch, it is expensive, and for good reason.)</p><p>The paperback will release after the 2000 available copies of the Keepsake Edition sell out.</p><h2 id="dan-s-10-koemmandments-of-capturing-attention" tabindex="-1">Dan’s 10 Koemmandments Of Capturing Attention <a class="header-anchor" href="#dan-s-10-koemmandments-of-capturing-attention" aria-label="Permalink to &quot;Dan’s 10 Koemmandments Of Capturing Attention&quot;">​</a></h2><p>As you are scrolling through social media or just reading content in general — try to keep an eye out for these tactics being used. That is the best way to solidify this information in your head. Notice when your attention is being captured and question “why.”</p><p>There are many ways to capture attention. I’ve found these to be the most replicable and practical (number 8 is the most important):</p><h3 id="_1-specific-numbers" tabindex="-1">1) Specific Numbers <a class="header-anchor" href="#_1-specific-numbers" aria-label="Permalink to &quot;1) Specific Numbers&quot;">​</a></h3><p>Using numbers in your hooks, headlines, or tweets will make people stop to see what the numbers relate to.</p><p>These can be in the form of:</p><ul><li><strong>Statistics</strong> — “There are 7 billion people on this earth”</li><li><strong>Dollar amounts</strong> — “Apples new $1175 iPhone has this new feature”</li><li><strong>Metrics</strong> — “I sent 322 cold emails” or “After 293 days…”</li><li><strong>Lists</strong> — “7 bad habits that are preventing you…”</li></ul><p>The more specific the number is, the more it catches people’s attention.</p><p>If you can’t make it super specific, that’s fine. Don’t stress it.</p><p>Here’s an example from me that was the deciding factor in many people joining Digital Economics (my course):</p><p><img src="'+t+'" alt=""></p><h3 id="_2-pattern-interrupts" tabindex="-1">2) Pattern Interrupts <a class="header-anchor" href="#_2-pattern-interrupts" aria-label="Permalink to &quot;2) Pattern Interrupts&quot;">​</a></h3><p>A pattern interrupt is something that breaks people out of their normal conditioned patterns.</p><p>If someone is scrolling on X and is used to a lot of political commentary, a well-formatted list tweet will make them stop their scroll.</p><p>Most of the things in this list are pattern interrupts.</p><h3 id="_3-negativity-bias" tabindex="-1">3) Negativity Bias <a class="header-anchor" href="#_3-negativity-bias" aria-label="Permalink to &quot;3) Negativity Bias&quot;">​</a></h3><p>The human brain is wired to remember and pay attention to negativity.</p><p>This does not mean you have to be negative all the time.</p><p>It means you need to use the negative forms of words.</p><p>If you are saying something positive, but the point is better illustrated in its negative form, use that.</p><p>“You are going to achieve great things.”</p><p>Compared to:</p><p>“You will never hit rock bottom again.”</p><p>The second is most potent. We remember negativity. It is the most relatable aspect of many people’s lives.</p><p>It can still be a positive message while leveraging the reader’s negativity bias.</p><h3 id="_4-group-callout" tabindex="-1">4) Group Callout <a class="header-anchor" href="#_4-group-callout" aria-label="Permalink to &quot;4) Group Callout&quot;">​</a></h3><p>This is simple, call out the specific person you are talking to.</p><ul><li>If you are in your 20’s…</li><li>Calling all creators, coaches, and freelancers!</li><li>Fathers are a gift to humankind…</li></ul><p>Even if your audience doesn’t fall into the specific group you are calling out, it will allow them to “pick a side” and compare themselves to what you are saying.</p><p>I talked about bodybuilders the other day. Even if people don’t consider themselves one, it helps paint a picture that they can relate to:</p><p><img src="'+o+'" alt=""></p><p>If someone talks about being a father, I can still relate because I will be a father one day. I will still pay attention to and take the advice.</p><p>This also works when it comes time to promote. You can call out exactly who the promotion is for and paint a picture of the problems they are struggling with.</p><h3 id="_5-problem-callout" tabindex="-1">5) Problem Callout <a class="header-anchor" href="#_5-problem-callout" aria-label="Permalink to &quot;5) Problem Callout&quot;">​</a></h3><p>Calling out the pains or problems people are experiencing will also make them relate to the post.</p><p>MOST people have encountered the same problem or pain as everyone else throughout their life.</p><p>If you can describe the feeling accurately, you have attention at your fingertips.</p><p>You don’t have to be dead on with this. Simply describing pain points will have people trying to relate their experiences to it. If they can relate, they will engage.</p><p>Here’s an example of calling out a pain as simple as “feeling terrible:”</p><p><img src="'+a+'" alt=""></p><h3 id="_6-potential-benefit" tabindex="-1">6) Potential Benefit <a class="header-anchor" href="#_6-potential-benefit" aria-label="Permalink to &quot;6) Potential Benefit&quot;">​</a></h3><p>The opposite of calling out a problem. Again, pains and benefits. Your mind needs to think in pains and benefits. That is your unique “why” behind whatever “what” or “how” you are writing about.</p><h3 id="_7-social-proof" tabindex="-1">7) Social Proof <a class="header-anchor" href="#_7-social-proof" aria-label="Permalink to &quot;7) Social Proof&quot;">​</a></h3><p>Again this is authoritative and implies an information gap.</p><p>When you flex your results or credentials, people automatically assume that you know more than them. They will take your content more seriously and read to find the information they are “missing.”</p><p>This works 100x better when it isn’t viewed as a “flex.”</p><p>Justin Welsh is the current king of this:</p><p><img src="'+i+'" alt=""></p><p>Use social proof to illustrate a point you are trying to make.</p><h3 id="_8-confidence-conviction" tabindex="-1">8) Confidence &amp; Conviction <a class="header-anchor" href="#_8-confidence-conviction" aria-label="Permalink to &quot;8) Confidence &amp; Conviction&quot;">​</a></h3><p><em><strong>This is by far the most important point here.</strong></em></p><p>You can create highly impactful posts with confidence alone — it allows other aspects of attention-grabbing to fall into place.</p><p>You are right about everything at this very point in time in relation to your goals, vision, beliefs, values, and everything else that forms your perspective of reality.</p><p>Your job is to have confidence and conviction in your beliefs and a credible or clear argument to back them up (if you have to).</p><p>Everyone is on social media to be told what to do in a confident way. Nobody is secure in their actions, choices, and beliefs. They are looking for someone to confirm them with confidence and give them that clarity to act.</p><p>Tools you can use to sound more confident:</p><ul><li>Eliminate words that imply uncertainty</li><li>Speak in absolutes when possible</li><li>Exaggerate your point to add energy</li></ul><p>Of course, do not abuse these for the sake of engagement.</p><p>Rather than saying:</p><p><em>“It may be wise if some people developed their skillset.”</em></p><p>Say:</p><p><em>“It is crucial that everyone on planet earth develops their skill set.”</em></p><p>Just by being confident, the words flow easier and the writing is more impactful.</p><p>I can go on to back that argument up with statistics or more creative firepower that I have in my mind.</p><p>Here is an example of me being confident in what I was saying:</p><p><img src="'+n+'" alt=""></p><p>This tweet got featured in a big newsletter and sparked a lot of controversy.</p><p>People were arguing whether or not it was the “greatest” skill. Some were proposing what their greatest skill was.</p><p>This made people comment and quote tweet, leading to more engagement and impressions.</p><p>I wrote this tweet in the moment when I had executed on an idea quickly. Doing that gave me a lot of joy, so I wanted to share that joy with others. It worked.</p><p>Is it 100% correct? No.</p><p>Was it 100% correct when I wrote it, through my perspective, relating to my personal experience?</p><p>Yes. At the time I was 100% convinced that that was the greatest skill.</p><p>I went on to add nuance in the replies. If I had added nuance in the actual tweet, it wouldn’t have done as well and opened up the opportunity to be featured in a big newsletter.</p><p>The people YOU want to attract aren’t the people that “hate” on your work.</p><p>Here is one other — a bit more extreme — example. Can you sense the motivational and practical energy “flowing through the screen?”</p><p><img src="'+r+'" alt=""></p><p>By the way, these types of high-energy advice posts pull in quite a bit of followers.</p><p>In summary — have some conviction behind what you are saying. This is not a skill that needs to be trained. It’s just a matter of writing the words in the most impactful way. Leaders don’t dance around the point they are trying to get across.</p><h3 id="_9-active-voice" tabindex="-1">9) Active Voice <a class="header-anchor" href="#_9-active-voice" aria-label="Permalink to &quot;9) Active Voice&quot;">​</a></h3><p>Active voice implies that there is a story. It eases people into what you are saying.</p><p>Passive voice is often boring and gives away the “mini-story” too early. There is no anticipation that makes people want to figure out what happened next.</p><p>When you are practicing writing posts, look up an article on active voice and use it to edit until you get the hang of it.</p><p>This also helps with being perceived as confident.</p><h3 id="_10-warnings-cautionary-advice" tabindex="-1">10) Warnings &amp; Cautionary Advice <a class="header-anchor" href="#_10-warnings-cautionary-advice" aria-label="Permalink to &quot;10) Warnings &amp; Cautionary Advice&quot;">​</a></h3><p>What should people look out for when they are trying to achieve something?</p><p>Can you warn them of something they will encounter as they are trying to reach where you are now?</p><p>When you are doing your weekly reflection, or just reflecting on your life, what roadblocks can you help people navigate?</p><p>This is best illustrated with this tweet. I hit on a hot topic like dopamine and warned them of another hot topic (then wrapped it up with confidence).</p><p>This sparked a LOT of controversy, but I have research to back up that point AND gave nuance in the replies to build a deeper connection with my audience:</p><p><img src="'+s+'" alt=""></p><h2 id="what-holds-attention" tabindex="-1">What Holds Attention? <a class="header-anchor" href="#what-holds-attention" aria-label="Permalink to &quot;What Holds Attention?&quot;">​</a></h2><p>Once the curiosity loop is opened, the mind feels committed to figuring out the rest of the story.</p><p>That is what holds attention — crafting a compelling story.</p><p>Stories are layers of metaphors, concepts, perspectives, and experiences that take people on a journey.</p><p>People want to understand the entire story. They want to know what came before, during, and after any given event (from capturing attention).</p><p>Here are 2 things to keep in mind when it comes to holding attention:</p><h3 id="_1-structure" tabindex="-1">1) Structure <a class="header-anchor" href="#_1-structure" aria-label="Permalink to &quot;1) Structure&quot;">​</a></h3><p>We aren’t in high school anymore. Long, professional paragraphs don’t matter and reduce readability. Especially on X — people log on to that platform to escape the professional world.</p><p>How do you improve the structure of all of your content?</p><ul><li><strong>Bullet lists</strong> — use numbers, bullets, and other tactics that help you break apart what you are saying. These lists create a “story” in themselves.</li><li><strong>Line breaks</strong> — use line breaks whenever possible, but don’t just add line breaks for the sake of it. Be creative. Use line breaks to emphasize specific sentences and help your writing flow.</li><li><strong>Starting short and concise</strong> — Use shorter sentences or paragraphs at the start of your content. Capture attention with short and punchy statements, then let loose and get creative with how your sentences flow.</li><li><strong>Break apart sentences</strong> — use parenthesis and “—” dashes over commas. This sentence is too long (until I make people want to know what are in these parenthesis).</li></ul><p>Here is an example of all of the above in one hook:</p><p><img src="'+p+'" alt=""></p><h3 id="_2-novel-perspectives" tabindex="-1">2) Novel Perspectives <a class="header-anchor" href="#_2-novel-perspectives" aria-label="Permalink to &quot;2) Novel Perspectives&quot;">​</a></h3><p>This requires you to get the bulk of your ideas from books, podcasts, or other longer-form content that gives more nuance to certain ideas.</p><p>Novelty increases dopamine levels in the brain. It brings more clarity to an idea that has been talked about over and over.</p><p>If you are getting all of your content from Twitter while trying to grow on Twitter — you will probably end up with the same perspective as everyone else.</p><p>Metaphors, personal experiences, and creating new concepts is how you achieve this.</p><p>This will be our prime focus in future modules, so hold tight on this for now (but keep it in mind so you can start making connections as you consume).</p><p>I was reading an article, learned about how a glass of water can create an acre of fog, and applied it to one of my sub-topics — mindfulness.</p><p><img src="'+l+'" alt=""></p><p>Content <em>consumption</em> (or research) is important. Specifically books, audiobooks, podcasts, or articles. Those will give you different perspectives on the things you love talking about.</p><h2 id="what-creates-engagement" tabindex="-1">What Creates Engagement? <a class="header-anchor" href="#what-creates-engagement" aria-label="Permalink to &quot;What Creates Engagement?&quot;">​</a></h2><p>Remember: <em><strong>People don’t remember what you say, they remember how you make them feel.</strong></em></p><p>Alan Watts may have been an alcoholic in his later years and cheated on his wives — which I have my own opinions about — but his work has changed my life for good. It gives me inspiration, clarity, and a new outlook on life.</p><p>I may remember some quotes of his, but the reason I remember them is because of the clarity they gave me. The feeling of having zero worries in the world. When I want to experience that again, I throw on an Alan Watts lecture.</p><p>YOU are but a humble messenger of a life-changing message.</p><p><strong>1) The feelings that come from education.</strong></p><p>Learning something new or gaining clarity on some aspect of their life raises dopamine levels in the brain.</p><p>You create clarity through novel perspectives, metaphors, stories, personal experiences, and other parts of your life that will help others understand what you are saying.</p><p>Your job is to “make sense” to a specific group of people.</p><p>You do this by sharing how certain topics make sense to you.</p><p><strong>2) The feelings that come from inspiration.</strong></p><p>Inspiration is different from motivation.</p><p>You are helping people connect the dots on their own, giving them the clarity to make their own decisions and change their behavior.</p><p>People feel good when they think they came up with the answer themselves — but will still attribute that feeling to you.</p><p><strong>3) The feeling that comes from entertainment.</strong></p><p>Can you throw in a joke, meme, or interesting point of view?</p><p>When you watch a movie, you are entertained through humor, drama, emotional parts of the story, and battles that spark excitement in you.</p><p>Entertainment, education, and inspiration are the main goals of your content.</p><p>I hope you enjoyed this one.</p><p>If you want to become a digital writer who controls the outcome of their life through the internet, check out read more in the <a href="https://thedankoe.com/blog/category/digital-writing/" target="_blank" rel="noreferrer">Digital Writer series</a>.</p><p>Dan Koe</p><p>P.S. The Art Of Focus is available for pre-order.</p><p>The hardcover book, the revamped physical planner, a keepsake coin, an invitation to in-person events, a private community, and more.</p><p><a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">Get your 1/2000 available copies here.</a></p>',171)])])}const I=h(d,[["render",g]]);export{_ as __pageData,I as default};
